function k({registerIndicator:m,sourceValues:h,nulls:o}){m({id:"oa-ccyc",name:"Ehlers Cyber Cycle (CCYC)",category:"Cycles",placement:"pane",inputs:[{key:"alpha",type:"number",label:"Alpha (damping)",default:.07,min:.01,max:.99,step:.01,tooltip:"High-pass cutoff. Lower damping gives a smoother, slower cycle; Ehlers uses 0.07."},{key:"source",type:"source",label:"Source",default:"hl2"}],plots:[{key:"cycle",type:"line",title:"Cycle",style:{color:"#ffeb3b",lineWidth:2}},{key:"trigger",type:"line",title:"Trigger",style:{color:"#ef5350",lineWidth:1}}],levels:()=>[{price:0,title:"Zero",color:"#8892a6",dashed:!0}],calc(n,a){const r=Math.min(.99,Math.max(.01,Number(a.alpha)||.07)),i=h(n,a.source??"hl2"),b=Math.pow(1-.5*r,2),N=2*(1-r),f=-Math.pow(1-r,2),s=n.length,c=new Array(s).fill(NaN),t=new Array(s).fill(NaN),p=new Array(s).fill(NaN);for(let e=0;e<s;e++){const l=Number.isFinite(i[e])?i[e]:0,y=e>=1&&Number.isFinite(i[e-1])?i[e-1]:l,u=e>=2&&Number.isFinite(i[e-2])?i[e-2]:l,g=e>=3&&Number.isFinite(i[e-3])?i[e-3]:l;if(c[e]=(l+2*y+2*u+g)/6,e<6)t[e]=(l-2*y+u)/4;else{const F=Number.isFinite(c[e-1])?c[e-1]:c[e],d=Number.isFinite(c[e-2])?c[e-2]:c[e],C=Number.isFinite(t[e-1])?t[e-1]:0,w=Number.isFinite(t[e-2])?t[e-2]:0;t[e]=b*(c[e]-2*F+d)+N*C+f*w}p[e]=e>=1&&Number.isFinite(t[e-1])?t[e-1]:0}return{cycle:o(t),trigger:o(p)}}})}export{k as default};
